import datetime as dt
def isg(d, n, dt=dt):
    while n:
        d += dt.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d
def esit(tahsisat, talep):
    kalan = tahsisat
    sonuc_d = {}
    bekleyen = dict(talep)
    while bekleyen and kalan > 0:
        pay = kalan / len(bekleyen)
        tamam = {k: v for k, v in bekleyen.items() if v <= pay}
        if not tamam:
            for k in bekleyen:
                sonuc_d[k] = pay
            kalan = 0
            break
        for k, v in tamam.items():
            sonuc_d[k] = v
            kalan -= v
            del bekleyen[k]
    return sonuc_d
